minimal_patch:
在 syncDailyBoard 的循环内，对已处于最终评审状态且本地已有 review_verified=true、review_receipt、accepted 与 status 一致的席位，先做只读幂等复核而不是进入可重置提交/评审路径。具体改动：在处理 generated_pending_sync/sync_unknown/submitted_pending_review/review_unknown/completed_draft_review/rejected_draft_review 之前，插入如下恢复分支（约30行）：

```js
const finalByLocal = ['completed_draft_review','rejected_draft_review'].includes(seat.status);
if (finalByLocal && seat.review_verified === true && seat.review_receipt && typeof seat.accepted === 'boolean' && seat.artifact) {
  try {
    const bytes = validateArtifact(root, record, agent, seat);
    if (digest(await readRemote(seat.artifact.path)) !== digest(bytes)) throw Error('remote_artifact_not_persisted');
    const observed = await snapshot();
    if (!fresh(observed, agent, now)) throw Error('snapshot_unavailable');
    const task = taskFor(observed, seat.assignment.id);
    const stable = task && ['completed_draft_review','rejected_draft_review'].includes(task.status)
      && task.evidence_path === seat.artifact.path
      && task.evidence_sha256 === seat.artifact.sha256
      && task.review?.evidence_sha256 === seat.review_receipt.evidence_sha256
      && (task.status === 'completed_draft_review') === seat.accepted;
    if (stable) {
      seat.sync_reason = 'final_review_already_bound_no_reverification';
      saveLedger(root, record);
      continue;
    }
  } catch {
    // 保留本地已绑定状态，不因瞬时远端失败降级；下一轮幂等复核。
    seat.sync_reason = 'final_review_remote_recheck_deferred';
    saveLedger(root, record);
    continue;
  }
}
```
